  'a3' => ', और पीडीएफ से वर्ड कनवर्टर,',
  'conclusion-para3' => 'ये सभी समान एक घंटे की विलोपन नीति का पालन करते हैं।',
  'faqs-heading' => 'अक्सर पूछे जाने वाले प्रश्नों',
  'faq1-question' => 'क्या पीडीएफ टूल कंपनी के कर्मचारी मेरी अपलोड की गई फ़ाइलें पढ़ सकते हैं?',
  'faq1-answer' => 'किसी भी क्लाउड सेवा के सिस्टम प्रशासकों के पास तकनीकी रूप से सर्वर स्टोरेज तक पहुंच होती है। प्रतिष्ठित सेवाओं में सख्त पहुंच नियंत्रण, सभी पहुंच की लॉगिंग और नीतियां होती हैं जो उपयोगकर्ता द्वारा अनुरोधित तकनीकी सहायता के अलावा किसी भी कारण से उपयोगकर्ता फ़ाइलों को देखने पर रोक लगाती हैं। उन दस्तावेज़ों के लिए जहां किसी भी मानवीय पहुंच में समस्या होगी, स्थानीय डेस्कटॉप सॉफ़्टवेयर का उपयोग करें।',
  'faq2-question' => 'यदि मेरी फ़ाइल सर्वर पर है तो सेवा हैक हो गई तो क्या होगा?',
  'faq2-answer' => 'यह जोखिम किसी भी क्लाउड सेवा के साथ मौजूद है। छोटी अवधारण विंडो और उच्च फ़ाइल वॉल्यूम के संयोजन का मतलब है कि उल्लंघन में किसी विशिष्ट फ़ाइल को लक्षित किए जाने की संभावना कम है। उन दस्तावेज़ों के लिए जहां कोई भी जोखिम अस्वीकार्य होगा, उनकी सुरक्षा प्रथाओं की परवाह किए बिना क्लाउड सेवाओं का उपयोग न करें।',
  'faq3-question' => 'क्या गुप्त ब्राउज़र विंडो का उपयोग ऑनलाइन टूल को सुरक्षित बनाता है?',
  'faq3-answer' => 'नहीं, गुप्त मोड आपके ब्राउज़र को स्थानीय इतिहास और कुकीज़ को सहेजने से रोकता है, लेकिन सर्वर पर क्या होता है उस पर इसका कोई प्रभाव नहीं पड़ता है। पीडीएफ टूल आपके ब्राउज़र के गोपनीयता मोड की परवाह किए बिना आपकी फ़ाइल को बिल्कुल उसी तरीके से प्राप्त करता है और संसाधित करता है।',
  'faq4-question' => 'मुझे कैसे पता चलेगा कि कोई पीडीएफ टूल जीडीपीआर के अनुरूप है?',
  'faq4-answer' => 'गोपनीयता नीति में एक विशिष्ट जीडीपीआर अनुभाग देखें जो ईयू डेटा संरक्षण कानून के तहत आपके अधिकारों का वर्णन करता है, डेटा नियंत्रक का नाम देता है, और डेटा अनुरोधों के लिए संपर्क जानकारी प्रदान करता है। यूरोपीय संघ के उपयोगकर्ताओं में काम करने वाली या उनकी सेवा करने वाली प्रतिष्ठित सेवाओं के पास यह होगा। यूरोपीय संघ के उपयोगकर्ताओं को सेवा प्रदान करने वाली सेवा में किसी भी जीडीपीआर उल्लेख का अभाव एक महत्वपूर्ण चेतावनी संकेत है।',
);
